import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    book = {}  # id -> [side, price, qty_remaining, seq]
    seq_counter = [0]

    def next_seq():
        seq_counter[0] += 1
        return seq_counter[0]

    def clean_buy():
        while buy_heap:
            negp, s, oid = buy_heap[0]
            if oid not in book or book[oid][2] <= 0:
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell():
        while sell_heap:
            p, s, oid = sell_heap[0]
            if oid not in book or book[oid][2] <= 0:
                heapq.heappop(sell_heap)
            else:
                break

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                del book[oid]
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None

        remaining = qty
        seq = next_seq()

        if side == 'buy':
            clean_sell()
            while remaining > 0 and sell_heap:
                p, s, sid = sell_heap[0]
                if price is not None and p > price:
                    break
                sinfo = book[sid]
                avail = sinfo[2]
                trade_qty = min(remaining, avail)
                trades.append([oid, sid, p, trade_qty])
                remaining -= trade_qty
                sinfo[2] -= trade_qty
                if sinfo[2] <= 0:
                    del book[sid]
                    heapq.heappop(sell_heap)
                clean_sell()
            if typ == 'limit' and remaining > 0:
                book[oid] = ['buy', price, remaining, seq]
                heapq.heappush(buy_heap, (-price, seq, oid))
        else:  # sell
            clean_buy()
            while remaining > 0 and buy_heap:
                negp, s, bid = buy_heap[0]
                p = -negp
                if price is not None and p < price:
                    break
                binfo = book[bid]
                avail = binfo[2]
                trade_qty = min(remaining, avail)
                trades.append([bid, oid, p, trade_qty])
                remaining -= trade_qty
                binfo[2] -= trade_qty
                if binfo[2] <= 0:
                    del book[bid]
                    heapq.heappop(buy_heap)
                clean_buy()
            if typ == 'limit' and remaining > 0:
                book[oid] = ['sell', price, remaining, seq]
                heapq.heappush(sell_heap, (price, seq, oid))

    return trades

